<!DOCTYPE html>
<html>
<head>
  <title>Sorting Visualizer</title>
  <style>
    body {
      background-color: #1e1e1e;
      color: #f0f0f0;
      font-family: sans-serif;
    }

    #container {
      width: 80%;
      margin: 20px auto;
      border: 1px solid #333;
      padding: 10px;
      background-color: #252526;
      overflow: hidden; /* Prevent bars from overflowing */
    }

    .bar {
      height: 10px;
      display: inline-block;
      width: 30px;
      margin: 3px;
      background-color: steelblue;
      color: white;
      text-align: center;
      line-height: 10px;
    }

    button {
      background-color: #333;
      color: #f0f0f0;
      border: none;
      padding: 8px 16px;
      margin: 5px;
      cursor: pointer;
      font-size: 16px;
    }

    button:hover {
      background-color: #444;
    }
  </style>
</head>
<body>
  <div id="container">
    <div id="bars"></div>
  </div>

  <button id="sort">Animate Sort</button>
  <button id="shuffle">Shuffle Array</button>
  <button id="reset">Reset</button>

  <script>
    const arrayLength = 10;
    let arr = [];
    const barsDiv = document.getElementById('bars');
    const sortButton = document.getElementById('sort');
    const shuffleButton = document.getElementById('shuffle');
    const resetButton = document.getElementById('reset');

    function init() {
      generateArray();
      renderArray();
    }

    function generateArray() {
      arr = [];
      for (let i = 0; i < arrayLength; i++) {
        arr.push(Math.floor(Math.random() * 100)); // Values between 0 and 99
      }
    }

    function renderArray() {
      barsDiv.innerHTML = '';
      for (let i = 0; i < arr.length; i++) {
        const bar = document.createElement('div');
        bar.classList.add('bar');
        bar.style.height = `${arr[i]}px`;
        barsDiv.appendChild(bar);
      }
    }

    function sortStep() {
      if (arr.length <= 1) return true;

      // Bubble Sort implementation for demonstration purposes
      let swapped = false;
      for (let i = 0; i < arr.length - 1; i++) {
        if (arr[i] > arr[i + 1]) {
          const temp = arr[i];
          arr[i] = arr[i + 1];
          arr[i + 1] = temp;
          swapped = true;
        }
      }

      renderArray();

      return !swapped; // Return true if no swaps were made in this iteration, indicating completion.
    }


    function sorted() {
      for (let i = 0; i < arr.length - 1; i++) {
        if (arr[i] > arr[i + 1]) {
          return false;
        }
      }
      return true;
    }

    window.viz = {
      array: function() {
        return [...arr]; // Return a copy to prevent external modification
      },
      setArray: function(a) {
        arr = a;
        renderArray();
      },
      sortStep: sortStep,
      sorted: sorted
    };

    shuffleButton.addEventListener('click', () => {
      generateArray();
    });

    resetButton.addEventListener('click', () => {
      init();
    });

    sortButton.addEventListener('click', () => {
      if (sortStep()) {
        sortButton.disabled = true;
      }
    });

    init();
  </script>
</body>
</html>
